import { formatEuros } from './money.js';
import { lineTotal, lineDiscount, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, lines: Array, ... }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const header = invoice.number ? `Invoice: ${invoice.number}` : 'Invoice: DRAFT';

  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok
    ? customerResult.value.name
    : `[Customer ${invoice.customerId}]`;

  const lineTexts = invoice.lines.map((line) => {
    const total = lineTotal(line);
    const discount = lineDiscount(line);
    let text = `${line.qty} x ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`;
    if (discount > 0) {
      text += ` (${line.discountPercent}% off: -${formatEuros(discount)})`;
    }
    return text;
  });

  const totals = invoiceTotals(invoice);

  const parts = [header, customerName, ...lineTexts];
  if (totals.discount > 0 || totals.vat > 0) {
    parts.push(`Subtotal: ${formatEuros(totals.subtotal)}`);
    if (totals.discount > 0) {
      parts.push(`Discount: -${formatEuros(totals.discount)}`);
    }
    if (totals.vat > 0) {
      parts.push(`VAT: +${formatEuros(totals.vat)}`);
    }
  }
  parts.push(`Total: ${formatEuros(totals.total)}`);
  return parts.join('\n');
}

