test('createInvoice with tier discount: affects final total', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);

  const expectedSubtotal = 10 * 9500;
  const expectedDiscount = Math.round((expectedSubtotal * 5) / 100);
  const amount = expectedSubtotal - expectedDiscount;
  const expectedVAT = Math.round((amount * 21) / 100);
  const expectedTotal = amount + expectedVAT;

  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, expectedTotal);
});

